//! The keyword list, generated by `tools/build_grammar.py` from the reference
//! grammar, so the compiler and the grammar can never disagree about it.

use std::collections::HashSet;
use std::sync::OnceLock;

const KEYWORDS: &str = include_str!("../../../grammar/keywords.txt");

/// How a word is classified before parsing.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WordKind {
    /// Reserved everywhere; never a name.
    Hard,
    /// A keyword only inside its own phrase; a name everywhere else.
    Soft,
    /// An ordinary name.
    Name,
}

struct Keywords {
    hard: HashSet<&'static str>,
    soft: HashSet<&'static str>,
}

fn keywords() -> &'static Keywords {
    static KEYWORDS_SET: OnceLock<Keywords> = OnceLock::new();
    KEYWORDS_SET.get_or_init(|| {
        let mut hard = HashSet::new();
        let mut soft = HashSet::new();
        for line in KEYWORDS.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            match line.split_once(' ') {
                Some(("hard", word)) => hard.insert(word),
                Some(("soft", word)) => soft.insert(word),
                _ => panic!("grammar/keywords.txt: unreadable line {line:?}"),
            };
        }
        Keywords { hard, soft }
    })
}

/// Classify a word.
pub fn classify(word: &str) -> WordKind {
    let k = keywords();
    if k.hard.contains(word) {
        WordKind::Hard
    } else if k.soft.contains(word) {
        WordKind::Soft
    } else {
        WordKind::Name
    }
}

/// Whether a word is any keyword, hard or soft.
pub fn is_keyword(word: &str) -> bool {
    classify(word) != WordKind::Name
}

/// The number of hard and soft keywords.
pub fn counts() -> (usize, usize) {
    let k = keywords();
    (k.hard.len(), k.soft.len())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn classifies_words() {
        assert_eq!(classify("return"), WordKind::Hard);
        assert_eq!(classify("add"), WordKind::Hard);
        assert_eq!(classify("version"), WordKind::Soft);
        assert_eq!(classify("windows"), WordKind::Name);
        assert_eq!(classify("give"), WordKind::Name);
    }

    #[test]
    fn list_is_not_empty() {
        let (hard, soft) = counts();
        assert!(hard > 100 && soft > 50, "{hard} hard, {soft} soft");
    }
}
